INSERT INTO compact_chat_evidence_guard SELECT IF(COUNT(*)=0,1,0) FROM compact_chat_evidence_columns e LEFT JOIN information_schema.columns c ON c.table_schema='__SOURCE_SCHEMA__' AND c.table_name=e.table_name AND c.column_name=e.column_name WHERE c.column_name IS NULL OR NOT(BINARY LOWER(c.column_type)<=>BINARY e.column_type) OR NOT(c.is_nullable<=>e.nullable) OR NOT(c.collation_name<=>e.collation_name) OR NOT(LOWER(c.column_default)<=>e.default_value) OR NOT(LOWER(c.extra)<=>e.extra) OR c.generation_expression<>'';
