INSERT INTO compact_chat_evidence_guard SELECT IF(COUNT(*)=0,1,0) FROM compact_chat_evidence_keys e LEFT JOIN (SELECT table_name,(index_name='PRIMARY') is_primary,GROUP_CONCAT(column_name ORDER BY seq_in_index) key_columns,SUM(sub_part IS NOT NULL) prefixes FROM information_schema.statistics WHERE table_schema='__SOURCE_SCHEMA__' AND table_name IN ('agent_message_execution','agent_workspace_turn_snapshot','agent_context_turn') AND non_unique=0 GROUP BY table_name,index_name) a ON e.table_name=a.table_name AND e.is_primary=a.is_primary AND e.key_columns=a.key_columns WHERE a.table_name IS NULL;
