INSERT INTO compact_chat_evidence_guard SELECT IF(COUNT(*)=0,1,0) FROM chat_message WHERE execution_run_id IS NOT NULL OR execution_owner_user_id IS NOT NULL OR execution_created_at IS NOT NULL OR execution_legacy_id IS NOT NULL OR execution_evidence_id IS NOT NULL OR snapshot_owner_user_id IS NOT NULL OR workspace_snapshot_json IS NOT NULL OR workspace_snapshot_sha256 IS NOT NULL OR workspace_snapshot_created_at IS NOT NULL OR workspace_snapshot_legacy_id IS NOT NULL OR snapshot_evidence_id IS NOT NULL OR context_owner_user_id IS NOT NULL OR context_sources_json IS NOT NULL OR context_sources_sha256 IS NOT NULL OR context_evidence_id IS NOT NULL;
