INSERT INTO compact_chat_evidence_guard SELECT IF(COUNT(*)=0,1,0) FROM `__SOURCE_SCHEMA__`.agent_message_execution WHERE NOT COALESCE((CONVERT_TZ(created_at,'__SOURCE_CHAT_OFFSET__','+00:00') IS NOT NULL AND TIMESTAMPDIFF(SECOND,CONVERT_TZ(created_at,'__SOURCE_CHAT_OFFSET__','+00:00'),created_at)=(IF(LEFT('__SOURCE_CHAT_OFFSET__',1)='-',-1,1)*(CAST(SUBSTRING('__SOURCE_CHAT_OFFSET__',2,2) AS SIGNED)*3600+CAST(SUBSTRING('__SOURCE_CHAT_OFFSET__',5,2) AS SIGNED)*60))),FALSE);
INSERT INTO compact_chat_evidence_guard SELECT IF(COUNT(*)=0,1,0) FROM `__SOURCE_SCHEMA__`.agent_workspace_turn_snapshot WHERE NOT COALESCE((CONVERT_TZ(created_at,'__SOURCE_CHAT_OFFSET__','+00:00') IS NOT NULL AND TIMESTAMPDIFF(SECOND,CONVERT_TZ(created_at,'__SOURCE_CHAT_OFFSET__','+00:00'),created_at)=(IF(LEFT('__SOURCE_CHAT_OFFSET__',1)='-',-1,1)*(CAST(SUBSTRING('__SOURCE_CHAT_OFFSET__',2,2) AS SIGNED)*3600+CAST(SUBSTRING('__SOURCE_CHAT_OFFSET__',5,2) AS SIGNED)*60))),FALSE);
