INSERT INTO compact_chat_evidence_guard SELECT IF(COUNT(*)=0,1,0) FROM `__SOURCE_SCHEMA__`.agent_context_turn WHERE NOT JSON_VALID(sources_json) OR NOT REGEXP_LIKE(sources_sha256,'^[A-Fa-f0-9]{64}$','c') OR NOT(BINARY LOWER(sources_sha256)<=>BINARY SHA2(sources_json,256));
INSERT INTO audit_event(event_id,kind,owner_user_id,resource_type,resource_id,session_id,message_id,run_id,action,content_sha256,occurred_at,payload_version,payload_json,legacy_source,legacy_key) SELECT CONCAT('legacy-chat-execution-',s.id),'MESSAGE_EXECUTION',s.user_id,'CHAT_MESSAGE',CAST(s.message_id AS CHAR),s.session_id,s.message_id,s.run_id,'RECORDED',SHA2(JSON_OBJECT('legacyId',CAST(s.id AS CHAR),'createdAtSource',DATE_FORMAT(s.created_at,'%Y-%m-%d %H:%i:%s.%f'),'sourceUtcOffset','__SOURCE_CHAT_OFFSET__'),256),CONVERT_TZ(s.created_at,'__SOURCE_CHAT_OFFSET__','+00:00'),1,JSON_OBJECT('legacyId',CAST(s.id AS CHAR),'createdAtSource',DATE_FORMAT(s.created_at,'%Y-%m-%d %H:%i:%s.%f'),'sourceUtcOffset','__SOURCE_CHAT_OFFSET__'),'agent_message_execution',CAST(s.id AS CHAR) FROM `__SOURCE_SCHEMA__`.agent_message_execution s;
INSERT INTO audit_event(event_id,kind,owner_user_id,resource_type,resource_id,session_id,message_id,run_id,action,content_sha256,occurred_at,payload_version,payload_json,legacy_source,legacy_key) SELECT CONCAT('legacy-chat-snapshot-',s.id),'MESSAGE_WORKSPACE_SNAPSHOT',s.user_id,'CHAT_MESSAGE',CAST(s.message_id AS CHAR),s.session_id,s.message_id,NULL,'RECORDED',s.snapshot_sha256,CONVERT_TZ(s.created_at,'__SOURCE_CHAT_OFFSET__','+00:00'),1,JSON_OBJECT('legacyId',CAST(s.id AS CHAR),'snapshotJson',s.snapshot_json,'createdAtSource',DATE_FORMAT(s.created_at,'%Y-%m-%d %H:%i:%s.%f'),'sourceUtcOffset','__SOURCE_CHAT_OFFSET__'),'agent_workspace_turn_snapshot',CAST(s.id AS CHAR) FROM `__SOURCE_SCHEMA__`.agent_workspace_turn_snapshot s;
INSERT INTO audit_event(event_id,kind,owner_user_id,resource_type,resource_id,session_id,message_id,run_id,action,content_sha256,occurred_at,payload_version,payload_json,legacy_source,legacy_key) SELECT SHA2(CONCAT('agent_context_turn:',CONCAT(s.user_id,':',CHAR_LENGTH(s.session_id),':',s.session_id,':',s.message_id)),256),'MESSAGE_CONTEXT_SOURCES',s.user_id,'CHAT_MESSAGE',CAST(s.message_id AS CHAR),s.session_id,s.message_id,NULL,'RECORDED',s.sources_sha256,NULL,1,JSON_OBJECT('sourcesJson',s.sources_json),'agent_context_turn',CONCAT(s.user_id,':',CHAR_LENGTH(s.session_id),':',s.session_id,':',s.message_id) FROM `__SOURCE_SCHEMA__`.agent_context_turn s;
INSERT INTO compact_chat_projection SELECT 'MESSAGE_EXECUTION',CAST(s.id AS CHAR),m.id,s.user_id,s.session_id,a.id FROM `__SOURCE_SCHEMA__`.agent_message_execution s JOIN chat_message m ON m.id=s.message_id AND BINARY m.session_id=BINARY s.session_id AND m.role='assistant' JOIN chat_session c ON BINARY c.session_id=BINARY m.session_id AND c.user_id=s.user_id JOIN audit_event a ON BINARY a.legacy_source=BINARY 'agent_message_execution' AND BINARY a.legacy_key=BINARY CAST(s.id AS CHAR);
INSERT INTO compact_chat_evidence_guard SELECT IF(COUNT(*)=0,1,0) FROM compact_chat_projection expected JOIN `__SOURCE_SCHEMA__`.agent_message_execution s ON BINARY expected.legacy_key=BINARY CAST(s.id AS CHAR) LEFT JOIN chat_message m ON m.id=expected.message_id WHERE expected.kind='MESSAGE_EXECUTION' AND (m.id IS NULL OR NOT(m.execution_evidence_id<=>expected.evidence_id) OR NOT(m.execution_owner_user_id<=>s.user_id) OR NOT(BINARY m.session_id<=>BINARY expected.session_id) OR NOT(BINARY m.execution_run_id<=>BINARY s.run_id) OR NOT(m.execution_created_at<=>CONVERT_TZ(s.created_at,'__SOURCE_CHAT_OFFSET__','+00:00')) OR NOT(m.execution_legacy_id<=>s.id));
