INSERT INTO compact_chat_evidence_guard SELECT IF(COUNT(*)=0,1,0) FROM compact_chat_projection expected JOIN `__SOURCE_SCHEMA__`.agent_workspace_turn_snapshot s ON BINARY expected.legacy_key=BINARY CAST(s.id AS CHAR) LEFT JOIN chat_message m ON m.id=expected.message_id WHERE expected.kind='MESSAGE_WORKSPACE_SNAPSHOT' AND (m.id IS NULL OR NOT(m.snapshot_evidence_id<=>expected.evidence_id) OR NOT(m.snapshot_owner_user_id<=>s.user_id) OR NOT(BINARY m.session_id<=>BINARY expected.session_id) OR NOT(BINARY m.workspace_snapshot_json<=>BINARY s.snapshot_json) OR NOT(BINARY m.workspace_snapshot_sha256<=>BINARY s.snapshot_sha256) OR NOT(m.workspace_snapshot_created_at<=>CONVERT_TZ(s.created_at,'__SOURCE_CHAT_OFFSET__','+00:00')) OR NOT(m.workspace_snapshot_legacy_id<=>s.id));
