INSERT INTO compact_chat_evidence_guard SELECT IF(COUNT(*)=0,1,0) FROM compact_chat_projection expected JOIN `__SOURCE_SCHEMA__`.agent_context_turn s ON BINARY expected.legacy_key=BINARY CONCAT(s.user_id,':',CHAR_LENGTH(s.session_id),':',s.session_id,':',s.message_id) LEFT JOIN chat_message m ON m.id=expected.message_id WHERE expected.kind='MESSAGE_CONTEXT_SOURCES' AND (m.id IS NULL OR NOT(m.context_evidence_id<=>expected.evidence_id) OR NOT(m.context_owner_user_id<=>s.user_id) OR NOT(BINARY m.session_id<=>BINARY expected.session_id) OR NOT(BINARY m.context_sources_json<=>BINARY s.sources_json) OR NOT(BINARY m.context_sources_sha256<=>BINARY s.sources_sha256));
