-- Independent V44/V45/V66 message evidence copy: AUTHORED_NOT_EXECUTED.
-- Distinct schemas, stopped source writers. __SOURCE_CHAT_OFFSET__ must be an evidenced DATETIME offset.
-- Run after ordinary chat rows are copied if current projections are required. Missing parents never discard evidence.
-- Old ids remain source identities; audit.id is an independent cursor. Preserve source AUTO_INCREMENT metadata in the migration receipt/backup.
-- No source DML, no sequence rewrite, no source FK, no inferred owner/session/run/time.
-- One connection; stop at the first error, ROLLBACK there, then close. Never --force.
SET NAMES utf8mb4;
CREATE TEMPORARY TABLE compact_chat_evidence_guard(valid INT NOT NULL CHECK(valid=1)) ENGINE=InnoDB;
CREATE TEMPORARY TABLE compact_chat_evidence_columns(table_name VARCHAR(64),column_name VARCHAR(64),column_type VARCHAR(64),nullable VARCHAR(3),collation_name VARCHAR(64),default_value VARCHAR(64),extra VARCHAR(64),PRIMARY KEY(table_name,column_name)) ENGINE=InnoDB;
CREATE TEMPORARY TABLE compact_chat_evidence_keys(table_name VARCHAR(64),is_primary BOOLEAN,key_columns VARCHAR(1024)) ENGINE=InnoDB;
START TRANSACTION;
CREATE TEMPORARY TABLE compact_chat_projection(kind VARCHAR(48),legacy_key VARCHAR(512) COLLATE utf8mb4_bin,message_id BIGINT,owner_user_id BIGINT,session_id VARCHAR(128) COLLATE utf8mb4_bin,evidence_id BIGINT UNSIGNED,PRIMARY KEY(kind,message_id)) ENGINE=InnoDB;
UPDATE chat_message m JOIN `__SOURCE_SCHEMA__`.agent_message_execution s ON m.id=s.message_id AND BINARY m.session_id=BINARY s.session_id AND m.role='assistant' JOIN chat_session c ON BINARY c.session_id=BINARY m.session_id AND c.user_id=s.user_id JOIN audit_event a ON BINARY a.legacy_source=BINARY 'agent_message_execution' AND BINARY a.legacy_key=BINARY CAST(s.id AS CHAR) SET m.execution_owner_user_id=s.user_id,m.execution_evidence_id=a.id,m.execution_run_id=s.run_id,m.execution_created_at=CONVERT_TZ(s.created_at,'__SOURCE_CHAT_OFFSET__','+00:00'),m.execution_legacy_id=s.id;
UPDATE chat_message m JOIN `__SOURCE_SCHEMA__`.agent_workspace_turn_snapshot s ON m.id=s.message_id AND BINARY m.session_id=BINARY s.session_id AND m.role='assistant' JOIN chat_session c ON BINARY c.session_id=BINARY m.session_id AND c.user_id=s.user_id JOIN audit_event a ON BINARY a.legacy_source=BINARY 'agent_workspace_turn_snapshot' AND BINARY a.legacy_key=BINARY CAST(s.id AS CHAR) SET m.snapshot_owner_user_id=s.user_id,m.snapshot_evidence_id=a.id,m.workspace_snapshot_json=s.snapshot_json,m.workspace_snapshot_sha256=s.snapshot_sha256,m.workspace_snapshot_created_at=CONVERT_TZ(s.created_at,'__SOURCE_CHAT_OFFSET__','+00:00'),m.workspace_snapshot_legacy_id=s.id;
UPDATE chat_message m JOIN `__SOURCE_SCHEMA__`.agent_context_turn s ON m.id=s.message_id AND BINARY m.session_id=BINARY s.session_id JOIN chat_session c ON BINARY c.session_id=BINARY m.session_id AND c.user_id=s.user_id JOIN audit_event a ON BINARY a.legacy_source=BINARY 'agent_context_turn' AND BINARY a.legacy_key=BINARY CONCAT(s.user_id,':',CHAR_LENGTH(s.session_id),':',s.session_id,':',s.message_id) SET m.context_owner_user_id=s.user_id,m.context_evidence_id=a.id,m.context_sources_json=s.sources_json,m.context_sources_sha256=s.sources_sha256;
COMMIT;
DROP TEMPORARY TABLE compact_chat_projection;
DROP TEMPORARY TABLE compact_chat_evidence_keys;
DROP TEMPORARY TABLE compact_chat_evidence_columns;
DROP TEMPORARY TABLE compact_chat_evidence_guard;
